    tags=['m_MT_RSTD_BKGS_MSR_ANNUITY']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'WI_BKGS_MSR_ANNUITY_SW_PRDT1' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   MT.BOOKINGS_MEASURE_KEY,
   MT.BKGS_MEASURE_TRANS_TYPE_CODE,
   MT.BOOKINGS_PROCESS_DATE,
   MT.SALES_TERRITORY_KEY,
   MT.SALES_REP_NUMBER,
   MT.DV_CONTRACT_DURATION,
   MT.DV_ANNUALIZED_FLG,
   MT.RU_SERVICE_CONTRACT_START_DTM,
   MT.RU_SERVICE_CONTRACT_END_DTM,
   MT.ANNUITY_TYPE,
   MT.ANNUITY_WEEK,
   MT.PER_MONTH_AMT * 12 ANNUITY_AMT,
   MT.DV_FMV_FLG,
   MT.ADJUSTMENT_CODE
FROM
   {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_STGDB') }}.WI_BKGS_MSR_ANNUITY_PRDT_AMORZ MT
WHERE
   RTRIM(ANNUITY_TYPE) in (COLLATE('Software', 'en-ci-rtrim'))
   AND (BOOKINGS_MEASURE_KEY, BKGS_MEASURE_TRANS_TYPE_CODE, BOOKINGS_PROCESS_DATE, COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'), SALES_TERRITORY_KEY, SALES_REP_NUMBER, ANNUITY_WEEK) NOT IN (
      SELECT
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'),
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         MAX(ANNUITY_WEEK) ANNUITY_WEEK
      FROM
         {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_STGDB') }}.WI_BKGS_MSR_ANNUITY_PRDT_AMORZ
      WHERE
         RTRIM(ANNUITY_TYPE) in (COLLATE('Software', 'en-ci-rtrim'))
      GROUP BY
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         ANNUITY_TYPE
   )
UNION ALL
SELECT
   MT.BOOKINGS_MEASURE_KEY,
   MT.BKGS_MEASURE_TRANS_TYPE_CODE,
   MT.BOOKINGS_PROCESS_DATE,
   MT.SALES_TERRITORY_KEY,
   MT.SALES_REP_NUMBER,
   MT.DV_CONTRACT_DURATION,
   MT.DV_ANNUALIZED_FLG,
   MT.RU_SERVICE_CONTRACT_START_DTM,
   MT.RU_SERVICE_CONTRACT_END_DTM,
   MT.ANNUITY_TYPE,
   MT.ANNUITY_WEEK,
   MT.PER_MONTH_AMT * (MOD(MT.DV_CONTRACT_DURATION, 12)) ANNUITY_AMT,
   MT.DV_FMV_FLG,
   MT.ADJUSTMENT_CODE
FROM
   {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_STGDB') }}.WI_BKGS_MSR_ANNUITY_PRDT_AMORZ MT
WHERE
   RTRIM(ANNUITY_TYPE) in (COLLATE('Software', 'en-ci-rtrim'))
   AND (BOOKINGS_MEASURE_KEY, BKGS_MEASURE_TRANS_TYPE_CODE, BOOKINGS_PROCESS_DATE, COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'), SALES_TERRITORY_KEY, SALES_REP_NUMBER, ANNUITY_WEEK) IN (
      SELECT
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'),
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         MAX(ANNUITY_WEEK) ANNUITY_WEEK
      FROM
         {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_STGDB') }}.WI_BKGS_MSR_ANNUITY_PRDT_AMORZ
      WHERE
         RTRIM(ANNUITY_TYPE) in (COLLATE('Software', 'en-ci-rtrim'))
      GROUP BY
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         ANNUITY_TYPE
   )
   AND MOD(MT.DV_CONTRACT_DURATION, 12) <> 0